// Generate TypeScript types from the newest schema copy in web/contracts/.
//
// The generated file is checked in, so a contract change shows up twice: as a
// diff in src/data/contract.gen.ts and as type errors wherever the site uses a
// field that changed. After the contract changes: copy the new version's
// schemas into web/contracts/<version>/, then run `npm run types`.
//
// The types describe the newest version. Older files (history/) can lack the
// fields a MINOR version added, so code reading such a field must allow for it
// being absent (e.g. `entry.results_complete ?? null`).
import { mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { compile } from "json-schema-to-typescript";

const WEB = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const COPIES = join(WEB, "contracts");
const VERSION = /^(\d+)\.(\d+)\.(\d+)$/;
const newest = readdirSync(COPIES)
  .filter((name) => VERSION.test(name))
  .sort((a, b) => {
    const [x, y] = [a, b].map((name) => VERSION.exec(name).slice(1).map(Number));
    return x[0] - y[0] || x[1] - y[1] || x[2] - y[2];
  })
  .at(-1);
if (!newest) throw new Error(`no schema copies in ${COPIES}`);
const CONTRACTS = join(COPIES, newest);
const OUT = join(WEB, "src", "data", "contract.gen.ts");

const SCHEMAS = [
  ["index.schema.json", "RunIndex"],
  ["snapshot.schema.json", "Snapshot"],
  ["track_record.schema.json", "TrackRecordSummary"],
];

/** Replace every {"$ref": "#/$defs/x"} with the definition itself. The $defs
 *  are tiny (a date pattern, a 0-1 number), and naming them would produce
 *  clashing types such as `Date`, which would hide JavaScript's own Date. */
function inlineDefs(node, defs) {
  if (Array.isArray(node)) return node.map((item) => inlineDefs(item, defs));
  if (node === null || typeof node !== "object") return node;
  if (typeof node.$ref === "string" && node.$ref.startsWith("#/$defs/")) {
    return inlineDefs(defs[node.$ref.slice("#/$defs/".length)], defs);
  }
  const out = {};
  for (const [key, value] of Object.entries(node)) {
    if (key !== "$defs") out[key] = inlineDefs(value, defs);
  }
  return out;
}

const parts = [
  `// GENERATED by scripts/gen-types.mjs from web/contracts/${newest}/*.schema.json. Do not edit by hand.\n` +
    "/* eslint-disable */\n",
];
for (const [file, name] of SCHEMAS) {
  const raw = JSON.parse(readFileSync(join(CONTRACTS, file), "utf8"));
  const schema = inlineDefs(raw, raw.$defs ?? {});
  // Name the root type ourselves rather than deriving it from the schema title.
  schema.title = name;
  parts.push(await compile(schema, name, { bannerComment: "", additionalProperties: false, format: false }));
}
mkdirSync(dirname(OUT), { recursive: true });
writeFileSync(OUT, parts.join("\n"));
console.log(`Wrote ${OUT}`);
